const N = parseInt(require('fs').readFileSync('/dev/stdin', 'utf8').trim(), 10);

const lines = [];
for (let i = 0; i < N; i++) {
  const row = [];
  for (let j = 0; j < N; j++) {
    row.push(Math.min(i + 1, j + 1, N - i, N - j));
  }
  lines.push(row.join(' '));
}
console.log(lines.join('\n'));
